{
  "rationales": {
    "A": "Koşullu olasılıkta örnek uzay en az bir zarın 3 geldiği 11 durumla sınırlanır ve her iki zarın 3 geldiği tek durum vardır.",
    "B": "İstenen durumun iki farklı şekilde gerçekleşebileceğini düşünerek pay kısmına hatalı şekilde 2 yazılmasıyla elde edilen yanlış seçenektir.",
    "C": "Örnek uzaydaki eleman sayısını doğru belirleyip istenen durum sayısını yanlışlıkla 3 olarak alan öğrencilerin yöneleceği hatalı seçenektir.",
    "D": "Koşullu olasılık formülünü yanlış uygulayarak istenen durum sayısını hatalı şekilde 4 olarak hesaplayan öğrencilerin tercih edeceği seçenektir.",
    "E": "Örnek uzayı doğru bulmasına rağmen istenen durum sayısını yanlışlıkla 5 olarak belirleyen öğrencilerin ulaştığı hatalı sonuçtur."
  },
  "misconception_tags": [
    "koşullu_olasılık_örnek_uzay_hatası",
    "bağımsız_olay_karışıklığı"
  ],
  "solution_steps": [
    "Adım 1: İki zardan en az birinin 3 geldiği tüm olası durumlar listelenerek örnek uzay kümesi oluşturulur.",
    "Adım 2: Bu koşulu sağlayan durumların sayısı 11 olarak belirlenir.",
    "Adım 3: Her iki zarın da 3 geldiği istenen durum sayısı 1 olarak tespit edilir.",
    "Adım 4: İstenen durum sayısının örnek uzay eleman sayısına oranıyla olasılık değeri 1/11 olarak hesaplanır."
  ],
  "expected_answer_formula": "1/11"
}

{
  "rationales": {
    "A": "Stendhal, realizmin öncülerinden biri olmasına rağmen parçada boş bırakılan yere getirilmesi gereken doğru sanatçı değildir.",
