    "eser_yazar_uyumsuzlugu",
    "edebi_akim_temsilcileri"
  ],
  "solution_steps": [
    "Adım 1: Paragraftaki ipuçlarından yola çıkarak realizm akımının öncüsü olan sanatçı belirlenir.",
    "Adım 2: Yazarın insanı çevreyle bir bütün olarak ele alan felsefesi ve edebi yönü incelenir.",
    "Adım 3: En ünlü eseri 'Kırmızı ve Siyah' olan ve seçeneklerde E ile eşleşen yazar tespit edilir."
  ],
  "expected_answer_formula": null
}

{
